    'vmu.report.enabled': true,
    'vmu.report.reports': [
      {
        name: 'v5r-outward-progress',
        trigger: { kind: 'period', everyMs: 900000 },
        template: '【自动汇报 {{ count }}】{{ name }}（{{ at }}）：本所仍在推进，详情见所内 Progress/。',
        to: ['office'],
        channel: 'digest',
