    {
      id: 'v5r.motion-box',
      kind: 'module',
      order: 310,
      on: ['meeting/motion'],
      failure: 'open',
      capabilities: ['trigger-workflow', 'record'],
      module: V5R_MOTION_BOX,
    },
    // ★ GOAL ROUND 3: THE PAPER REPLY DISPATCHER ENTRY WAS REMOVED, WITH THE REASON KEPT HERE.
