    {
      id: 'v5r.artifact-counter',
      kind: 'module',
      order: 320,
      on: ['tools/result', 'math/job-settled', 'lean/job-settled'],
      failure: 'open',
      capabilities: ['trigger-workflow', 'record'],
      module: V5R_ARTIFACT_COUNTER,
